'use client';

import { motion } from 'framer-motion';

interface PulseRingProps {
  width?: number;
  height?: number;
  color?: string;
  ringCount?: number;
  thickness?: number;
  isAnimating?: boolean;
}

export function PulseRing({
  width = 60,
  height = 60,
  color = "currentColor",
  ringCount = 3,
  thickness = 3,
  isAnimating = true,
}: PulseRingProps) {
  const centerX = width / 2;
  const centerY = height / 2;
  const baseRadius = Math.min(width, height) * 0.15;
  const duration = 1.5;

  return (
    <svg
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-label="Loading"
      role="img"
    >
      {Array.from({ length: ringCount }).map((_, i) => (
        <motion.circle
          key={i}
          cx={centerX}
          cy={centerY}
          r={baseRadius}
          stroke={color}
          strokeWidth={thickness}
          fill="none"
          animate={{
            scale: [0.5, 1.5],
            opacity: [1, 0],
          }}
          transition={{
            duration,
            repeat: isAnimating ? Infinity : 0,
            delay: (duration / ringCount) * i,
            ease: 'easeOut',
          }}
          style={{ originX: `${centerX}px`, originY: `${centerY}px` }}
        />
      ))}
    </svg>
  );
}
